-- Supplier, service relationship, reconciled statement and in-app collaboration.
CREATE TABLE ty_outsource_supplier(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),owner_company_id bigint REFERENCES ty_company(id),
 code text NOT NULL,name text NOT NULL,region_code text NOT NULL CHECK(region_code IN('CN','HK')),currency_code text NOT NULL CHECK(currency_code IN('CNY','HKD')),
 status text NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),qualification_status text NOT NULL DEFAULT 'pending' CHECK(qualification_status IN('pending','verified','expired')),
 qualification_ref text NOT NULL DEFAULT '',qualification_valid_to date,contacts jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(contacts)='array'),
 billing_title text NOT NULL DEFAULT '',bank_name text NOT NULL DEFAULT '',bank_account_last4 text NOT NULL DEFAULT '' CHECK(bank_account_last4 ~ '^([0-9]{4})?$'),
 notes text NOT NULL DEFAULT '',created_by bigint NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,code),UNIQUE(id,group_id),
 CHECK((region_code='CN' AND currency_code='CNY') OR(region_code='HK' AND currency_code='HKD'))
);
CREATE TABLE ty_outsource_contract(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,supplier_id bigint NOT NULL,code text NOT NULL,name text NOT NULL,
 service_kind text NOT NULL CHECK(service_kind IN('staffing_outsource','dispatch','payroll_agency')),
 valid_from date NOT NULL,valid_to date NOT NULL CHECK(valid_to>=valid_from),status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','ended')),
 pricing jsonb NOT NULL CHECK(jsonb_typeof(pricing)='object'),share_payroll_details boolean NOT NULL DEFAULT false,owner_account_id bigint REFERENCES sys_account(id),
 terms text NOT NULL DEFAULT '',created_by bigint NOT NULL,UNIQUE(group_id,code),UNIQUE(id,group_id),
 FOREIGN KEY(supplier_id,group_id)REFERENCES ty_outsource_supplier(id,group_id)
);
CREATE TABLE ty_outsource_contract_company(
 contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),company_id bigint NOT NULL REFERENCES ty_company(id),PRIMARY KEY(contract_id,company_id)
);
CREATE TABLE ty_outsource_engagement(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),person_id bigint NOT NULL REFERENCES ty_person(id),
 company_id bigint NOT NULL REFERENCES ty_company(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 valid_from date NOT NULL,valid_to date CHECK(valid_to IS NULL OR valid_to>=valid_from),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','ended')),
 service_role text NOT NULL,legal_employer_name text NOT NULL,created_by bigint NOT NULL,UNIQUE(contract_id,person_id,valid_from)
);
CREATE TABLE ty_outsource_portal_user(
 account_id bigint PRIMARY KEY REFERENCES sys_account(id),group_id bigint NOT NULL,supplier_id bigint NOT NULL,
 FOREIGN KEY(supplier_id,group_id)REFERENCES ty_outsource_supplier(id,group_id)
);
CREATE TABLE ty_outsource_bill(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),period date NOT NULL CHECK(extract(day FROM period)=1),
 version integer NOT NULL DEFAULT 1 CHECK(version>0),supersedes_id bigint REFERENCES ty_outsource_bill(id),revision integer NOT NULL DEFAULT 0,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','shared','disputed','agreed')),
 note text NOT NULL DEFAULT '',snapshot jsonb,shared_by bigint,shared_at timestamptz,
 hr_confirmed_by bigint,hr_confirmed_at timestamptz,vendor_confirmed_by bigint,vendor_confirmed_at timestamptz,
 created_by bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(contract_id,period,version),
 CHECK((status='draft')=(snapshot IS NULL AND shared_at IS NULL)),
 CHECK(status<>'agreed' OR(hr_confirmed_by IS NOT NULL AND vendor_confirmed_by IS NOT NULL))
);
CREATE TABLE ty_outsource_bill_line(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bill_id bigint NOT NULL REFERENCES ty_outsource_bill(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 person_id bigint REFERENCES ty_person(id),item_code text NOT NULL CHECK(item_code IN('employee_net','withheld_tax','employee_contribution','employer_contribution','insurance','service_fee','tax_fee','other','adjustment','service_hours')),
 description text NOT NULL,quantity numeric(18,6) NOT NULL,unit_price numeric(18,6) NOT NULL,amount numeric(18,2) GENERATED ALWAYS AS(round(quantity*unit_price,2)) STORED,
 source_ref jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(source_ref)='object'),created_by bigint NOT NULL
);
CREATE TABLE ty_outsource_thread(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),person_id bigint REFERENCES ty_person(id),bill_id bigint REFERENCES ty_outsource_bill(id),
 category text NOT NULL CHECK(category IN('attendance','onboarding','offboarding','payroll','billing','other')),subject text NOT NULL,
 status text NOT NULL DEFAULT 'waiting_hr' CHECK(status IN('waiting_hr','waiting_vendor','waiting_employee','resolved')),
 due_date date,created_by bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),resolved_by bigint,resolved_at timestamptz
);
CREATE TABLE ty_outsource_message(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,thread_id bigint NOT NULL REFERENCES ty_outsource_thread(id),author_id bigint NOT NULL REFERENCES sys_account(id),
 visibility text NOT NULL CHECK(visibility IN('shared','hr_vendor','internal')),body text NOT NULL CHECK(length(btrim(body))BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ty_outsource_audit(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id bigint NOT NULL,action text NOT NULL,entity_kind text NOT NULL,entity_id bigint NOT NULL,
 before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ty_demo_name_assignment(person_id bigint PRIMARY KEY REFERENCES ty_person(id),full_name text NOT NULL,version text NOT NULL,assigned_by bigint NOT NULL);
CREATE FUNCTION fn_ty_outsource_relation_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE c public.ty_outsource_contract%ROWTYPE;s public.ty_outsource_supplier%ROWTYPE;e public.ty_employment%ROWTYPE;b public.ty_outsource_bill%ROWTYPE;emp public.ty_outsource_engagement%ROWTYPE;gid bigint;
BEGIN
 IF TG_TABLE_NAME='ty_outsource_supplier' THEN
  IF NEW.owner_company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.owner_company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商所属公司与集团不一致';END IF;
  IF TG_OP='UPDATE' THEN IF NEW.group_id<>OLD.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商不能移动到其他集团';END IF;END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id;
 IF TG_TABLE_NAME='ty_outsource_contract_company' THEN
  IF NOT EXISTS(SELECT 1 FROM public.ty_company co CROSS JOIN LATERAL public.fn_ty_company_locale(co.id) l JOIN public.ty_outsource_supplier v ON v.id=c.supplier_id WHERE co.id=NEW.company_id AND co.group_id=c.group_id AND l.region_code=v.region_code AND l.currency_code=v.currency_code)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务公司须属于同集团且地区币种与供应商一致';END IF;
 ELSIF TG_TABLE_NAME='ty_outsource_engagement' THEN
  PERFORM pg_advisory_xact_lock(209209,NEW.person_id::integer);
  SELECT * INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
  IF NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company WHERE contract_id=c.id AND company_id=NEW.company_id)OR e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.group_id<>c.group_id OR NEW.valid_from<c.valid_from OR coalesce(NEW.valid_to,c.valid_to)>c.valid_to THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务关系的人员、用工记录、公司或期限与合同不一致';END IF;
  IF c.service_kind='staffing_outsource' AND e.employment_type<>'outsourced' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员外包须使用明确外包服务关系，不能冒充直营劳动关系';END IF;
  IF c.service_kind='payroll_agency' AND e.employment_type='outsourced' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬代发不改变原用人单位劳动关系';END IF;
 ELSIF TG_TABLE_NAME='ty_outsource_bill' THEN
  IF NEW.period>c.valid_to OR NEW.period+interval '1 month'<=c.valid_from THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单月份不在服务合同有效期';END IF;
  IF NEW.supersedes_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_outsource_bill x WHERE x.id=NEW.supersedes_id AND x.contract_id=c.id AND x.period=NEW.period AND x.version+1=NEW.version AND x.status IN('disputed','agreed'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='更正账单须承接同合同同月的争议或已确认版本';END IF;
 ELSIF TG_TABLE_NAME='ty_outsource_thread' THEN
  IF NEW.person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_outsource_engagement WHERE contract_id=c.id AND person_id=NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='沟通人员不在本服务合同';END IF;
  IF NEW.bill_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_outsource_bill WHERE id=NEW.bill_id AND contract_id=c.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='沟通账单不属于本合同';END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER ty_outsource_supplier_guard BEFORE INSERT OR UPDATE ON ty_outsource_supplier FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_relation_guard();
CREATE TRIGGER ty_outsource_scope_guard BEFORE INSERT OR UPDATE ON ty_outsource_contract_company FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_relation_guard();
CREATE TRIGGER ty_outsource_engagement_guard BEFORE INSERT OR UPDATE ON ty_outsource_engagement FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_relation_guard();
CREATE TRIGGER ty_outsource_bill_relation BEFORE INSERT OR UPDATE ON ty_outsource_bill FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_relation_guard();
CREATE TRIGGER ty_outsource_thread_guard BEFORE INSERT OR UPDATE ON ty_outsource_thread FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_relation_guard();
CREATE FUNCTION fn_ty_outsource_bill_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE fund record;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.status='agreed' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已双方确认的账单不可改写，须建立更正版本';END IF;
  IF NEW.contract_id<>OLD.contract_id OR NEW.period<>OLD.period OR NEW.version<>OLD.version OR NEW.supersedes_id IS DISTINCT FROM OLD.supersedes_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单合同月份版本不可移动';END IF;
  IF OLD.status<>'draft' AND (NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.revision<>OLD.revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已共享的账单快照不可改写';END IF;
 END IF;
 IF NEW.status='agreed' THEN
  FOR fund IN SELECT DISTINCT(source_ref->>'row_id')::bigint row_id FROM public.ty_outsource_bill_line WHERE bill_id=NEW.id AND source_ref->>'kind'='payroll'ORDER BY row_id LOOP
   PERFORM pg_advisory_xact_lock(209210,fund.row_id::integer);
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.ty_outsource_bill_line x JOIN public.ty_outsource_bill_line y ON y.source_ref->>'kind'='payroll'AND y.source_ref->>'row_id'=x.source_ref->>'row_id'AND y.source_ref->>'component'=x.source_ref->>'component' JOIN public.ty_outsource_bill other ON other.id=y.bill_id WHERE x.bill_id=NEW.id AND x.source_ref->>'kind'='payroll'AND other.status='agreed'AND other.contract_id<>NEW.contract_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一工资资金分项已在另一合同确认，不能重复结算';END IF;
 END IF;
 IF NEW.status<>'draft' AND(NEW.snapshot IS NULL OR jsonb_array_length(NEW.snapshot)=0)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='共享账单须冻结非空明细';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_outsource_bill_guard BEFORE INSERT OR UPDATE ON ty_outsource_bill FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_bill_guard();
CREATE FUNCTION fn_ty_outsource_line_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE b public.ty_outsource_bill%ROWTYPE;c public.ty_outsource_contract%ROWTYPE;r public.ty_payroll_row%ROWTYPE;p public.ty_payroll_batch%ROWTYPE;expected numeric;component text;minutes numeric;
BEGIN
 SELECT * INTO b FROM public.ty_outsource_bill WHERE id=NEW.bill_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN IF NEW.bill_id<>OLD.bill_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='费用明细不能移动到其他账单';END IF;END IF;
 IF b.status<>'draft' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已共享账单明细只读，请建立更正版本';END IF;
 SELECT * INTO c FROM public.ty_outsource_contract WHERE id=b.contract_id;
 IF NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company WHERE contract_id=c.id AND company_id=NEW.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单费用公司不在本服务合同';END IF;
 IF NEW.person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_outsource_engagement e WHERE e.contract_id=c.id AND e.person_id=NEW.person_id AND e.company_id=NEW.company_id AND e.valid_from<b.period+interval '1 month' AND(e.valid_to IS NULL OR e.valid_to>=b.period))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单人员须在本合同当月有效服务范围';END IF;
 IF c.service_kind='payroll_agency' AND NEW.item_code IN('employee_net','withheld_tax','employee_contribution','employer_contribution') AND NEW.source_ref->>'kind' IS DISTINCT FROM 'payroll' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发资金项目须保留锁定工资来源，差异另列有依据的调整项';END IF;
 IF NEW.item_code='adjustment' AND length(btrim(coalesce(NEW.source_ref->>'reason','')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='调整项目须填写独立依据';END IF;
 IF NEW.source_ref->>'kind'='payroll' THEN
  SELECT * INTO r FROM public.ty_payroll_row WHERE id=(NEW.source_ref->>'row_id')::bigint;SELECT * INTO p FROM public.ty_payroll_batch WHERE id=r.batch_id;
  IF r.id IS NULL OR p.status<>'confirmed' OR p.period<>to_char(b.period,'YYYY-MM') OR p.group_id<>c.group_id OR r.person_id IS DISTINCT FROM NEW.person_id OR r.company_id<>NEW.company_id OR c.service_kind<>'payroll_agency' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发资金来源须对应同月同人的已确认工资与代发合同';END IF;
  component:=NEW.source_ref->>'component';
  IF component IS DISTINCT FROM (CASE NEW.item_code WHEN 'employee_net' THEN 'net_pay' WHEN 'withheld_tax' THEN 'cn_tax' WHEN 'employee_contribution' THEN 'employee_contribution' WHEN 'employer_contribution' THEN 'employer_contribution' END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金项目与工资来源分项不一致';END IF;
  IF component IN('net_pay','employee_contribution','employer_contribution')THEN expected:=(r.result_data->'totals'->>component)::numeric;
  ELSIF component='cn_tax' THEN SELECT(value->>'amount')::numeric INTO expected FROM jsonb_array_elements(r.result_data->'items')WHERE value->>'code'='cn_tax';
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不支持的代发资金项目';END IF;
  IF expected IS NULL OR round(NEW.quantity*NEW.unit_price,2)<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发资金金额与锁定工资来源不一致';END IF;
 END IF;
 IF NEW.source_ref->>'kind'='attendance' THEN
  IF NEW.item_code<>'service_hours' OR c.service_kind='payroll_agency' OR NOT EXISTS(SELECT 1 FROM public.ty_roster_period rp WHERE rp.id=(NEW.source_ref->>'period_id')::bigint AND rp.group_id=c.group_id AND rp.period=b.period AND rp.status='closed')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务工时来源须对应本合同同月已封存考勤';END IF;
  SELECT coalesce(sum(s.credited_minutes),0)INTO minutes FROM public.v_ty_time_segment s JOIN public.ty_outsource_engagement e ON e.employment_id=s.employment_id AND e.company_id=s.work_company_id AND e.person_id=s.person_id WHERE e.contract_id=c.id AND e.person_id=NEW.person_id AND e.company_id=NEW.company_id AND s.period_id=(NEW.source_ref->>'period_id')::bigint AND s.employment_id=(NEW.source_ref->>'employment_id')::bigint AND s.work_date>=e.valid_from AND(e.valid_to IS NULL OR s.work_date<=e.valid_to);
  IF minutes<=0 OR abs(NEW.quantity*60-minutes)>0.00003 OR NEW.unit_price IS DISTINCT FROM(c.pricing->>'unit_price')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='结算服务工时或单价与封存来源及合同不一致';END IF;
 END IF;
 UPDATE public.ty_outsource_bill SET revision=revision+1 WHERE id=b.id;RETURN NEW;
END $$;
CREATE TRIGGER ty_outsource_line_guard BEFORE INSERT OR UPDATE ON ty_outsource_bill_line FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_line_guard();
CREATE FUNCTION fn_ty_outsource_bill_decide(p_id bigint,p_actor bigint,p_action text,p_revision integer,p_note text)RETURNS text LANGUAGE plpgsql SET search_path='' AS $$
DECLARE b public.ty_outsource_bill%ROWTYPE;c public.ty_outsource_contract%ROWTYPE;vendor boolean;hr boolean;lines jsonb;
BEGIN
 SELECT * INTO b FROM public.ty_outsource_bill WHERE id=p_id FOR UPDATE;SELECT * INTO c FROM public.ty_outsource_contract WHERE id=b.contract_id;
 IF b.id IS NULL OR b.revision<>p_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单不存在或明细已变化，请刷新后核对';END IF;
 IF length(btrim(coalesce(p_note,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单操作需至少四字依据';END IF;
 vendor:=EXISTS(SELECT 1 FROM public.ty_outsource_portal_user WHERE account_id=p_actor AND supplier_id=c.supplier_id AND group_id=c.group_id);
 hr:=NOT EXISTS(SELECT 1 FROM public.ty_outsource_portal_user WHERE account_id=p_actor)AND public.fn_role_can(p_actor,'outsource_bill','write');
 IF p_action='share' AND hr AND b.status='draft' THEN
  SELECT jsonb_agg(to_jsonb(x)ORDER BY x.id)INTO lines FROM public.ty_outsource_bill_line x WHERE bill_id=b.id;
  IF lines IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='空账单不能共享';END IF;
  UPDATE public.ty_outsource_bill SET status='shared',snapshot=lines,shared_by=p_actor,shared_at=clock_timestamp()WHERE id=b.id;
 ELSIF p_action='dispute' AND(vendor OR hr)AND b.status='shared' THEN
  UPDATE public.ty_outsource_bill SET status='disputed',note=p_note WHERE id=b.id;
 ELSIF p_action='confirm' AND(vendor OR hr)AND b.status='shared' THEN
  IF vendor THEN UPDATE public.ty_outsource_bill SET vendor_confirmed_by=p_actor,vendor_confirmed_at=clock_timestamp()WHERE id=b.id;
  ELSE UPDATE public.ty_outsource_bill SET hr_confirmed_by=p_actor,hr_confirmed_at=clock_timestamp()WHERE id=b.id;END IF;
  UPDATE public.ty_outsource_bill SET status='agreed' WHERE id=b.id AND hr_confirmed_by IS NOT NULL AND vendor_confirmed_by IS NOT NULL;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='当前身份或账单状态不能执行此操作';END IF;
 INSERT INTO public.ty_outsource_audit(actor_id,action,entity_kind,entity_id,before_data,after_data)SELECT p_actor,p_action,'bill',b.id,to_jsonb(b),to_jsonb(x)FROM public.ty_outsource_bill x WHERE x.id=b.id;
 RETURN(SELECT status FROM public.ty_outsource_bill WHERE id=b.id);
END $$;
CREATE TRIGGER ty_outsource_bill_keep BEFORE DELETE ON ty_outsource_bill FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_outsource_line_keep BEFORE DELETE ON ty_outsource_bill_line FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_outsource_message_keep BEFORE UPDATE OR DELETE ON ty_outsource_message FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_outsource_audit_keep BEFORE UPDATE OR DELETE ON ty_outsource_audit FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
