CREATE FUNCTION fn_ty_outsource_contract_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE s public.ty_outsource_supplier%ROWTYPE;
BEGIN
 SELECT * INTO s FROM public.ty_outsource_supplier WHERE id=NEW.supplier_id;
 IF s.group_id<>NEW.group_id OR(s.status<>'active' AND NEW.status='active')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同供应商集团或启用状态不匹配';END IF;
 IF TG_OP='UPDATE' THEN IF EXISTS(SELECT 1 FROM public.ty_outsource_engagement WHERE contract_id=OLD.id)OR EXISTS(SELECT 1 FROM public.ty_outsource_bill WHERE contract_id=OLD.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发生服务或账单的合同保留原版本，请建立新合同';END IF;END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_outsource_contract_guard BEFORE INSERT OR UPDATE ON ty_outsource_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_outsource_contract_guard();
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT id,'outsource_self',true,true FROM sys_role WHERE code IN('ty_group_hr_director','ty_company_hr_director');

CREATE UNIQUE INDEX ty_outsource_fund_once_per_bill ON ty_outsource_bill_line(bill_id,(source_ref->>'row_id'),(source_ref->>'component'))WHERE source_ref->>'kind'='payroll';
